    {
      "section": "1.5.5",
      "label": "",
      "text": "The applicability of the correction matrix shall be veriﬁed in production processing on science data.",
      "id": null
    },
    {
      "section": "1.5.6",
      "label": "",
      "text": "The DMS shall produce on an as-needed basis a dark current correction image, which is constructed from multiple, closed-shutter exposures of appropriate duration.",
