      "label": "",
      "text": "The eﬀectiveness of the Dark Correction shall be veriﬁed in production processing on science data.",
      "id": null
    },
    {
      "section": "1.5.7",
      "label": "",
      "text": "The DMS shall produce on an as-needed basis an image that corrects for the color-dependent, pixel-to-pixel non-uniformity in the detector response.",
      "id": null
    },
    {
      "section": "1.5.7",
      "label": "",
      "text": "The images in the cube shall be constructed from exposures at multiple wavelengths of a uniformly illuminated source.",
      "id": null
    },
    {
      "section": "1.5.7",
      "label": "",
      "text": "The eﬀectiveness of the ﬂat-ﬁeld shall be veriﬁed in production processing on science data.",
      "id": null
    },
    {
      "section": "1.5.8",
      "label": "",
      "text": "The DMS shall produce on an as-needed basis an image that corrects for the non-uniform illumination of the ﬂat-ﬁeld calibration apparatus on the focal plane.",
      "id": null
    },
    {
      "section": "1.5.8",
      "label": "",
      "text": "The eﬀectiveness of the Illumination Correction shall be veriﬁed in production processing on science data.",
      "id": null
    },
    {
      "section": "1.5.9",
      "label": "",
      "text": "The DMS shall produce on an as-needed basis an image that corrects for detector fringing.",
      "id": null
    },
    {
      "section": "1.5.9",
      "label": "",
      "text": "The eﬀectiveness of the Fringe Correction shall be veriﬁed in production processing on science data.",
      "id": null
    },
    {
